"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The fixer File', 'author': 'Signature original', 'genre': 'City Shadows', 'chapters': [{'n': 1, 'title': 'The Client', 'text': "The rain had been falling on Grand Central Station since Tuesday, and Hank Mercer was thinking about closing the office when she walked in — or he, or they; trouble doesn't care about pronouns, only about timing. What they carried was a photograph with the face torn out.\n\n'I need you to find out what this means,' the client said, laying a photograph with the face torn out on the desk like a bet. Hank Mercer had seen a hundred such objects. They all meant the same thing: somebody was lying, and somebody was going to bleed.\n\nHank Mercer took the case. Not for the money — the money was insulting — but because a photograph with the face torn out had a look Hank Mercer recognized: the look of the one honest thing in a dirty town."}, {'n': 2, 'title': 'The Streets Talk', 'text': "Ruby sang the late set and slipped Hank Mercer a note between songs: a name, an address, a warning. 'They're watching you now,' she breathed. Hank Mercer tipped her and meant it.\n\nBack at the office, Hank Mercer spread the pieces out: a photograph with the face torn out, the ledger page, Ruby's note. The shape of it was the fixer, big as a building. And Hank Mercer was just one detective with a gun and a grudge against lies.\n\nHank Mercer started where every case starts: the bars. Lou poured whiskey and talked about the fixer's new operation, about money moving through Grand Central Station like blood through a bad heart."}, {'n': 3, 'title': "The Dame's Story", 'text': "'Why should I trust you?' Hank Mercer asked. She had no answer that wasn't tears, and Hank Mercer had stopped buying tears during the war. But a photograph with the face torn out was real, and the ledger was real, and that was enough.\n\nSister Agnes didn't like it. 'Dames,' Sister Agnes said, 'are how detectives get killed.' Hank Mercer agreed and kept the case anyway. Some habits are stronger than sense.\n\nHank Mercer took photographs with hands that didn't shake. Evidence. The one thing the fixer couldn't buy, beat, or bury. a photograph with the face torn out had led here, as a photograph with the face torn out always does, to the rotten center."}, {'n': 4, 'title': 'The Squeeze', 'text': "the fixer squeezed back. First the office: tossed, the safe cracked, a photograph with the face torn out's copy gone — but Hank Mercer keeps the originals where no one looks. Then Sister Agnes: a warning delivered with fists in an alley off Grand Central Station.\n\nSister Agnes showed up bloody and grinning. 'They hit like accountants,' Sister Agnes said. Hank Mercer felt the cold anger settle in, the kind that doesn't shout, just aims.\n\nThe dame vanished. Of course she did. Hank Mercer found her scarf in the office, red as a warning, and underneath it a note: 'Forgive me. They have my brother.' So that was the price. Everyone has one."}, {'n': 5, 'title': 'The Confrontation', 'text': "The dame got her brother back and Hank Mercer got the rest of the fee, which was more than the insulting original. She cried. Hank Mercer didn't buy the tears but didn't charge for the shoulder, either.\n\nThat night it rained again, washing Grand Central Station clean for an hour. Hank Mercer stood at the window with a photograph with the face torn out — the case closed, the ledger in the DA's hands. the truth is the only clean thing, Hank Mercer thought. Even here. Especially here.\n\n'You're finished,' Hank Mercer said. the fixer smiled the smile of someone who has bought judges. 'Am I?' Then Sister Agnes opened the door with the district attorney, and Ruby, and the dame's brother, alive, and the smile died."}, {'n': 6, 'title': 'Last Call', 'text': "The phone rang. Hank Mercer picked it up. 'Hank Mercer Investigations,' Hank Mercer said, and listened, and smiled the thin smile of someone who knows exactly how much trouble costs. 'the truth is the only clean thing. I'll take the case.'\n\nLou poured a double on the house. Ruby sang the song she only sings when she means it. Sister Agnes's ribs were taped, but Sister Agnes drank anyway, doctor's orders being for other people.\n\nGrand Central Station kept being Grand Central Station: rain, neon, lies, and now and then — now and then — a little justice, served neat, no ice. Hank Mercer could live with that. Hank Mercer had lived with worse."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

